<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { onLoad, onUnload } from '@dcloudio/uni-app'
import AppPage from '../../components/AppPage.vue'
import Icon from '../../components/Icon.vue'
import EmptyState from '../../components/EmptyState.vue'
import PhotoThumb from '../../components/PhotoThumb.vue'
import { useHealthStore,newId } from '../../stores/health'
import { foodCategories } from '../../data/foods'
import { dateKey } from '../../domain/dates'
import { mealKeys, mealNames } from '../../domain/types'
import type { Food, Meal, MealEntry, Nutrition } from '../../domain/types'
import { portion } from '../../domain/nutrition'
import { back, confirm, display, numeric, toast } from '../../utils/ui'
import { chooseImage,persistPhoto,resolvePhoto,removePhoto } from '../../services/photos'
const store=useHealthStore(),id=ref(''),date=ref(dateKey()),meal=ref<Meal>('breakfast'),grams=ref('100'),mode=ref('library'),search=ref(''),category=ref('全部'),selected=ref(''),error=ref(''),saving=ref(false),favorite=ref(false)
const custom=reactive({name:'',state:'',kcal:'',protein:'',carbs:'',fat:''})
const photoRequested=ref(false)
const photo=ref(''),photoSrc=ref(''),photoBusy=ref(false)
let originalPhoto='',saved=false,disposed=false,originalEntry:MealEntry|undefined
const nutrientFields=[{key:'kcal' as const,label:'热量',unit:'kcal'},{key:'protein' as const,label:'蛋白质',unit:'g'},{key:'carbs' as const,label:'碳水',unit:'g'},{key:'fat' as const,label:'脂肪',unit:'g'}]
const foods=computed(()=>store.allFoods.filter(x=>(category.value==='全部'||(category.value==='常吃'?store.data.favorites.includes(x.id):category.value==='自定义'?x.custom:x.category===category.value))&&(`${x.name}${x.state}`).includes(search.value.trim())))
const selectedFood=computed(()=>(()=>{const f=store.allFoods.find(x=>x.id===selected.value);return originalEntry&&originalEntry.foodId===selected.value&&f?{...f,name:originalEntry.name,...originalEntry.per100}:f})())
const preview=computed(()=>{let n:Nutrition={kcal:0,protein:0,carbs:0,fat:0};if(mode.value==='custom')for(const f of nutrientFields)n[f.key]=Math.max(0,Number(custom[f.key])||0);else if(selectedFood.value)n=selectedFood.value;return portion(n,Math.max(0,Number(grams.value)||0))})
onLoad(q=>{store.hydrate();photoRequested.value=q?.photo==='1';if(q?.food){selected.value=q.food;favorite.value=store.data.favorites.includes(q.food)}if(q?.date)date.value=q.date;if(q?.meal&&mealKeys.includes(q.meal as Meal))meal.value=q.meal as Meal;if(q?.filter==='favorites')category.value='常吃';if(q?.id){id.value=q.id;originalEntry=store.data.meals.find(x=>x.id===q.id);if(!originalEntry){toast('这条记录已不存在');back();return}const e=originalEntry;date.value=e.date;meal.value=e.meal;grams.value=String(e.grams);selected.value=e.foodId;favorite.value=store.data.favorites.includes(e.foodId);originalPhoto=e.photo||'';photo.value=originalPhoto;if(photo.value)resolvePhoto(photo.value).then(url=>photoSrc.value=url).catch(()=>toast('附件已不可用，可以重新选择'));const f=store.allFoods.find(x=>x.id===e.foodId);if(f?.custom){mode.value='custom';Object.assign(custom,{name:e.name,state:f.state,kcal:String(e.per100.kcal),protein:String(e.per100.protein),carbs:String(e.per100.carbs),fat:String(e.per100.fat)})}}})
onUnload(()=>{disposed=true;if(!saved&&photo.value&&photo.value!==originalPhoto)void removePhoto(photo.value)})
function selectFood(food:Food){selected.value=food.id;favorite.value=store.data.favorites.includes(food.id)}
async function attachPhoto(){if(photoBusy.value)return;photoBusy.value=true;try{const path=await chooseImage();if(!path)return;const reference=await persistPhoto(path);if(disposed){await removePhoto(reference);return}if(photo.value&&photo.value!==originalPhoto)await removePhoto(photo.value);photo.value=reference;photoSrc.value=await resolvePhoto(reference)}catch(e){toast((e as Error).message||'照片没有保存成功')}finally{photoBusy.value=false}}
function previewPhoto(){uni.previewImage({urls:[photoSrc.value]})}
async function clearPhoto(){if(photo.value&&photo.value!==originalPhoto)await removePhoto(photo.value);photo.value='';photoSrc.value=''}
async function save(){if(saving.value||photoBusy.value)return;error.value='';try{const amount=numeric(grams.value,'食物份量',0.1,10000,true)!;let food:Food|undefined;if(mode.value==='custom'){if(!custom.name.trim())throw new Error('请填写食物名称');if(!custom.state.trim())throw new Error('请填写生熟状态或品牌说明');food={id:selectedFood.value?.custom?selectedFood.value.id:newId(),name:custom.name.trim(),state:custom.state.trim(),category:'自定义',art:'salad',custom:true,kcal:numeric(custom.kcal,'每100克热量',0,1000,true)!,protein:numeric(custom.protein,'每100克蛋白质',0,100,true)!,carbs:numeric(custom.carbs,'每100克碳水',0,100,true)!,fat:numeric(custom.fat,'每100克脂肪',0,100,true)!}}else food=selectedFood.value;if(!food)throw new Error('先选择一种食物，或切换到自定义');saving.value=true;const entry:MealEntry={id:id.value||newId(),date:date.value,meal:meal.value,foodId:food.id,name:food.name,grams:amount,per100:{kcal:food.kcal,protein:food.protein,carbs:food.carbs,fat:food.fat},art:food.art,photo:photo.value||undefined};if(store.saveMeal(entry,food.custom?food:undefined,favorite.value)){saved=true;if(originalPhoto&&originalPhoto!==photo.value)await removePhoto(originalPhoto);back();toast('饮食已保存')}}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function remove(){if(await confirm('删除这项食物？','删除后会同步更新当天摄入和每周回顾。')){if(store.deleteMeal(id.value)){saved=true;await removePhoto(originalPhoto);if(photo.value!==originalPhoto)await removePhoto(photo.value);back();toast('记录已删除')}}}
</script>
<template><AppPage :title="id?'编辑饮食':'记录饮食'"><text class="eyebrow">ONE MEAL AT A TIME</text><text class="page-title">{{ id?'调整这一餐':'记下这一餐' }}</text><text class="page-description">不必完美精确，真实记录就很好。</text><view class="row-between food-date mt-24"><picker mode="date" :value="date" :end="dateKey()" @change="date=$event.detail.value"><view class="row gap-8"><Icon name="calendar" :size="17"/><text>{{ date }}</text><text class="muted">▾</text></view></picker><text class="pill">手动记录</text></view><view class="metric-tabs mt-16"><button role="button" v-for="key in mealKeys" :key="key" class="metric-tab" :class="{active:meal===key}" @click="meal=key">{{ mealNames[key] }}</button></view><button role="button" v-if="photoRequested && !photoSrc" class="btn-secondary mt-16" :disabled="photoBusy" @click="attachPhoto"><Icon name="camera" :size="19"/>先选择餐食照片，再手动填写</button><view class="section"><view class="row-between mb-16"><text class="section-title">选择食物</text><button role="button" class="text-link" @click="mode=mode==='library'?'custom':'library';error=''">{{ mode==='library'?'+ 自定义食物':'返回食物库' }}</button></view><template v-if="mode==='library'"><view class="input-wrap search-wrap"><Icon name="search" tone="muted" :size="18"/><input aria-label="搜索食物" v-model="search" placeholder="搜索食物，如米饭、鸡胸肉" maxlength="30"/><button role="button" v-if="search" class="icon-button plain small" aria-label="清空搜索" @click="search=''"><Icon name="close" tone="muted" :size="14"/></button></view><scroll-view scroll-x class="category-scroll"><view class="category-list"><button role="button" v-for="cat in foodCategories" :key="cat" class="category-item" :class="{active:category===cat}" @click="category=cat">{{ cat }}</button></view></scroll-view><view class="food-options"><button role="button" v-for="food in foods" :key="food.id" class="food-option" :class="{chosen:selected===food.id}" @click="selectFood(food)"><PhotoThumb :art="food.art"/><view class="grow food-option-text"><view class="food-option-name"><text>{{ food.name }}</text><Icon v-if="store.data.favorites.includes(food.id)" name="star" tone="orange" :size="12"/></view><text class="helper">{{ food.state }} · {{ food.kcal }} kcal / 100g</text></view><view class="select-check"><Icon v-if="selected===food.id" name="check" tone="white" :size="12"/></view></button><EmptyState v-if="!foods.length" title="这里还没有食物" :detail="category==='常吃'?'保存饮食时勾选「加入常吃」，下次就能快速找到。':'换个关键词，或者创建自定义食物。'" icon="search" :compact="true"/></view><text class="helper mt-16">内置数据为每100克可食部参考值，不含额外烹饪油及酱料；品牌食品以包装标签为准。</text></template><template v-else><view class="field"><text class="field-label">食物名称</text><view class="input-wrap"><input aria-label="食物名称" v-model="custom.name" placeholder="例如：自制鸡肉三明治" maxlength="30"/></view></view><view class="field"><text class="field-label">生熟状态 / 品牌说明</text><view class="input-wrap"><input aria-label="生熟状态或品牌" v-model="custom.state" placeholder="例如：熟、无糖、某品牌" maxlength="40"/></view></view><text class="helper mb-16">请填写每100克的营养值；没有的营养素请核实后填0。</text><view class="form-grid"><view v-for="field in nutrientFields" :key="field.key" class="field"><text class="field-label">{{ field.label }}</text><view class="input-wrap"><input :aria-label="field.label" v-model="custom[field.key]" type="digit" placeholder="每100克"/><text class="input-unit">{{ field.unit }}</text></view></view></view></template></view>
<view class="section"><view class="field"><text class="field-label">这一餐吃了多少</text><view class="input-wrap portion-input"><input aria-label="食物份量" v-model="grams" type="digit" placeholder="100"/><text class="input-unit">克 g</text></view><text class="helper mt-16">按所选食物的生熟状态称重，份量支持小数。</text></view><view class="portion-preview"><view v-for="f in nutrientFields" :key="f.key"><text class="portion-number number">{{ display(preview[f.key],f.key==='kcal'?0:1) }}</text><text class="portion-label">{{ f.label }} {{ f.unit }}</text></view></view><button role="button" class="favorite-toggle" @click="favorite=!favorite"><view class="checkbox" :class="{checked:favorite}"><Icon v-if="favorite" name="check" tone="white" :size="12"/></view><text>加入常吃，下次快速记录</text></button></view>
<view class="section"><view class="section-heading"><text class="section-title">餐食照片</text><text class="section-caption">选填</text></view><template v-if="photoSrc"><image :src="photoSrc" class="photo-preview" mode="aspectFill" @click="previewPhoto"/><view class="row-between mt-16"><button role="button" class="text-link" @click="attachPhoto">更换照片</button><button role="button" class="danger-link" @click="clearPhoto">移除照片</button></view></template><button role="button" v-else class="photo-upload" :disabled="photoBusy" @click="attachPhoto"><Icon name="camera" :size="25"/><text>{{ photoBusy?'正在保存照片…':'拍摄或选择一张照片' }}</text><text class="helper">仅作为附件，不进行自动识别</text></button></view><text v-if="error" class="error-message">{{ error }}</text><view class="save-bar"><button role="button" class="btn-primary" :disabled="saving||photoBusy" @click="save"><Icon name="check" tone="white" :size="18"/>{{ saving?'正在保存…':'保存这一餐' }}</button><button role="button" v-if="id" class="delete-button danger-link" @click="remove">删除这项食物</button></view></AppPage></template>
<style scoped>.food-date{font-size:12px}.search-wrap{background:#eeefe7;border-color:transparent}.category-scroll{width:100%;white-space:nowrap;margin:13px 0}.category-list{display:flex;gap:7px;padding:2px 0 5px}.category-item{flex-shrink:0;font-size:10px;color:var(--muted);padding:7px 11px;border-radius:9px}.category-item.active{background:var(--sage);color:var(--green);font-weight:600}.food-options{max-height:330px;overflow-y:auto;border:1px solid var(--line);border-radius:16px;background:var(--white)}.food-option{display:flex;align-items:center;gap:12px;padding:12px;border-bottom:1px solid var(--line);width:100%;text-align:left;justify-content:flex-start}.food-option:last-child{border:0}.food-option.chosen{background:#edf3e6}.food-option .photo-thumb{width:44px;height:44px;border-radius:11px}.food-option-name{font-size:13px;display:flex;align-items:center;gap:5px;margin-bottom:4px}.food-option .helper{font-size:10px}.select-check{width:19px;height:19px;border:1px solid #dce3d3;border-radius:50%;display:flex;align-items:center;justify-content:center}.chosen .select-check{background:var(--green);border-color:var(--green)}.portion-input input{font-size:25px;font-weight:600;height:34px}.portion-preview{display:grid;grid-template-columns:repeat(4,1fr);padding:18px 12px;background:#e9efdf;border-radius:14px;text-align:center}.portion-number{display:block;font-size:21px;font-weight:600}.portion-label{display:block;font-size:9px;color:#7d8b72;margin-top:7px}.favorite-toggle{display:flex;gap:8px;justify-content:flex-start;font-size:12px;color:#77866c;margin-top:18px}.checkbox{width:17px;height:17px;border-radius:5px;border:1px solid #cdd7c1;display:flex;align-items:center;justify-content:center}.checkbox.checked{background:var(--green);border-color:var(--green)}.photo-upload{display:flex;flex-direction:column;gap:12px;border:1px dashed #ccd9c3;background:#eff3e9;border-radius:15px;padding:26px 12px;width:100%;color:var(--green);font-size:12px}.photo-upload .helper{font-size:10px}.delete-button{padding:18px 0 0;width:100%;font-size:12px}</style>
